import { useState, useOptimistic, useRef, startTransition } from 'react';

export function Chat({ api = '/api/chat' }) {
  const [messages, setMessages] = useState([]); // только подтверждённые сообщения
  const [shown, addOptimistic] = useOptimistic(messages, (current, msg) =>
    current.some((m) => m.id === msg.id)
      ? current // уже есть в реальном state (например, пришло извне): не показываем дважды
      : [...current, { ...msg, sending: true }]
  );
  const [draft, setDraft] = useState('');
  const [error, setError] = useState(null);
  const controllerRef = useRef(null);

  const patch = (id, fn) =>
    setMessages((list) => list.map((m) => (m.id === id ? fn(m) : m)));

  async function streamInto(body, replyId) {
    const reader = body.pipeThrough(new TextDecoderStream()).getReader();
    let buffer = '';
    let frame = 0;
    const flush = () => {
      frame = 0;
      const chunk = buffer;
      buffer = '';
      patch(replyId, (m) => ({ ...m, text: m.text + chunk })); // один рендер на кадр
    };
    let status = 'done';
    try {
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += value;
        if (!frame) frame = requestAnimationFrame(flush);
      }
    } catch (e) {
      status = e.name === 'AbortError' ? 'stopped' : 'failed'; // Stop — нормальный исход
    } finally {
      if (frame) cancelAnimationFrame(frame);
      if (buffer) flush();
      patch(replyId, (m) => ({ ...m, status })); // частичный текст остаётся в любом случае
      controllerRef.current = null;
    }
  }

  function send(e) {
    e.preventDefault();
    const text = draft.trim();
    if (!text) return;
    setDraft(''); // срочное обновление: поле очищается сразу
    setError(null);
    const userMsg = { id: crypto.randomUUID(), role: 'user', text };
    const replyId = crypto.randomUUID();
    const controller = new AbortController();
    controllerRef.current = controller;

    startTransition(async () => {
      addOptimistic(userMsg); // видно сразу и держится, пока Action не завершён
      let res;
      try {
        res = await fetch(api, {
          method: 'POST',
          body: JSON.stringify({ text }),
          signal: controller.signal,
        });
        if (!res.ok) throw new Error('HTTP ' + res.status);
      } catch (err) {
        // ничего не зафиксировано, оптимистичное сообщение исчезнет само
        startTransition(() => {
          setDraft((d) => d || text); // возвращаем текст в поле
          if (err.name !== 'AbortError') setError(err.message);
        });
        return;
      }
      // сервер принял: фиксируем сообщение и пустой ответ
      startTransition(() => {
        setMessages((list) => [
          ...list,
          { ...userMsg, status: 'sent' },
          { id: replyId, role: 'assistant', text: '', status: 'streaming' },
        ]);
      });
      streamInto(res.body, replyId); // БЕЗ await: Action заканчивается здесь
    });
  }

  return (
    <form onSubmit={send}>
      <ul>
        {shown.map((m) => (
          <li key={m.id} data-role={m.role} data-status={m.sending ? 'sending' : m.status}>
            {m.text}
          </li>
        ))}
      </ul>
      {error && <p role="alert">Not sent: {error}</p>}
      <textarea value={draft} onChange={(e) => setDraft(e.target.value)} />
      <button type="submit">Send</button>
      <button type="button" onClick={() => controllerRef.current?.abort()}>Stop</button>
    </form>
  );
}

import Anthropic from '@anthropic-ai/sdk';

const client = new Anthropic(); // ключ из ANTHROPIC_API_KEY
const MODEL = process.env.CLAUDE_MODEL ?? 'claude-opus-5-5'; // актуальный id модели бери из документации

export async function POST(req: Request): Promise<Response> {
  const { text } = await req.json();
  const stream = client.messages.stream(
    { model: MODEL, max_tokens: 1024, messages: [{ role: 'user', content: text }] },
    { signal: req.signal }, // браузер ушёл: отменяем вызов модели
  );
  const encoder = new TextEncoder();
  const body = new ReadableStream<Uint8Array>({
    start(controller) {
      stream.on('text', (delta) => controller.enqueue(encoder.encode(delta)));
      stream.on('finalMessage', () => controller.close()); // генерация закончилась штатно
      stream.on('error', (err) => controller.error(err));
      stream.on('abort', () => {}); // отменили сами: это не ошибка
    },
    cancel() {
      stream.abort(); // наш ответ никто не читает: останавливаем генерацию
    },
  });
  return new Response(body, { headers: { 'content-type': 'text/plain; charset=utf-8' } });
}

